#Requires -Version 5.1
$ErrorActionPreference = "Stop"

$RepoRoot = "C:\Users\moham\fidelity-image-viewer"
if (-not (Test-Path $RepoRoot)) {
    Write-Host "Repo not found at $RepoRoot, using current directory..." -ForegroundColor Yellow
    $RepoRoot = (Get-Location).Path
}
Set-Location $RepoRoot
Write-Host "==> Fixing Lovable Build & Preview Crash + Applying All UI/UX & Sync Upgrades..." -ForegroundColor Cyan

function Write-RepoFile {
    param(
        [string]$RelativePath,
        [string]$Base64Content
    )
    $FullPath = Join-Path $RepoRoot ($RelativePath -replace "/", "\")
    $Dir = Split-Path $FullPath -Parent
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host "  [OK] Updated $RelativePath" -ForegroundColor Green
}

Write-RepoFile -RelativePath "src/lib/queryPersist.ts" -Base64Content ""
Write-RepoFile -RelativePath "src/lib/queries.ts" -Base64Content ""
Write-RepoFile -RelativePath "src/router.tsx" -Base64Content ""
Write-RepoFile -RelativePath "src/lib/roundScoring.ts" -Base64Content ""
Write-RepoFile -RelativePath "src/lib/f1-parsers.ts" -Base64Content ""
Write-RepoFile -RelativePath "src/lib/f1-live-sources.ts" -Base64Content ""
Write-RepoFile -RelativePath "src/lib/f1-sync.functions.ts" -Base64Content ""
Write-RepoFile -RelativePath "src/lib/stewards.functions.ts" -Base64Content ""
Write-RepoFile -RelativePath "src/components/DriverPicker.tsx" -Base64Content ""
Write-RepoFile -RelativePath "src/components/SprintGrid.tsx" -Base64Content ""
Write-RepoFile -RelativePath "src/components/SiteHeader.tsx" -Base64Content ""
Write-RepoFile -RelativePath "src/routes/predict.tsx" -Base64Content ""
Write-RepoFile -RelativePath "src/routes/sprint.tsx" -Base64Content ""
Write-RepoFile -RelativePath "src/routes/leaderboard.tsx" -Base64Content ""

Write-Host "`n==> Step 1: Running TypeScript Check (npx tsc --noEmit)..." -ForegroundColor Cyan
npx tsc --noEmit
if ($LASTEXITCODE -ne 0) {
    Write-Error "TypeScript check failed! See errors above."
    exit $LASTEXITCODE
}
Write-Host "  [PASS] Zero TypeScript errors!" -ForegroundColor Green

Write-Host "`n==> Step 2: Running Production Build (npm run build)..." -ForegroundColor Cyan
