Write-Host "`n==> Step 3: Staging, committing, and pushing to GitHub..." -ForegroundColor Cyan
git add src/lib/queryPersist.ts src/lib/queries.ts src/router.tsx src/lib/roundScoring.ts src/lib/f1-parsers.ts src/lib/f1-live-sources.ts src/lib/f1-sync.functions.ts src/lib/stewards.functions.ts src/components/DriverPicker.tsx src/components/SprintGrid.tsx src/components/SiteHeader.tsx src/routes/predict.tsx src/routes/sprint.tsx src/routes/leaderboard.tsx
